83	
84	#define AGENT_POOL_SLOTS AGENT_MAX_TOOL_CALLS
85	
86	typedef struct {
87	    char* buffers[AGENT_POOL_SLOTS];
88	    bool in_use[AGENT_POOL_SLOTS];
89	    size_t buf_size;
90	    int count;
91	    pthread_mutex_t lock;
92	} agent_mem_pool_t;
93	
94	/**
95	 * Initialize a memory pool with `count` pre-allocated buffers.
96	 * Returns OK on success, ERROR if allocation fails.
97	 */
98	static inline int agent_pool_init(agent_mem_pool_t* pool, size_t buf_size,
99	    int count)
100	{
101	    if (count > AGENT_POOL_SLOTS)
102	        count = AGENT_POOL_SLOTS;
103	
104	    memset(pool, 0, sizeof(*pool));
105	    pool->buf_size = buf_size;
106	    pool->count = count;
107	    pthread_mutex_init(&pool->lock, NULL);
108	
109	    for (int i = 0; i < count; i++) {
110	        pool->buffers[i] = calloc(1, buf_size);
111	        if (!pool->buffers[i]) {
112	            /* Partial init: free what we got */
113	            for (int j = 0; j < i; j++)
114	                free(pool->buffers[j]);
115	            return ERROR;
116	        }
117	        pool->in_use[i] = false;
118	    }
119	    return OK;
120	}
121	
122	/**
123	 * Acquire a buffer from the pool. Returns NULL if all slots busy.
124	 */
125	static inline char* agent_pool_acquire(agent_mem_pool_t* pool)
126	{
127	    char* buf = NULL;
128	    pthread_mutex_lock(&pool->lock);
129	    for (int i = 0; i < pool->count; i++) {
130	        if (!pool->in_use[i]) {
131	            pool->in_use[i] = true;
132	            pool->buffers[i][0] = '\0';
133	            buf = pool->buffers[i];
134	            break;
135	        }
136	    }
137	    pthread_mutex_unlock(&pool->lock);
138	    return buf;
139	}
