141	/**
142	 * Release a buffer back to the pool.
143	 */
144	static inline void agent_pool_release(agent_mem_pool_t* pool, char* buf)
145	{
146	    if (!buf)
147	        return;
148	    pthread_mutex_lock(&pool->lock);
149	    for (int i = 0; i < pool->count; i++) {
150	        if (pool->buffers[i] == buf) {
151	            pool->in_use[i] = false;
152	            break;
153	        }
154	    }
155	    pthread_mutex_unlock(&pool->lock);
156	}
