233	 */
234	static inline char* agent_stream_detach(agent_stream_buf_t* sb)
235	{
236	    char* p = sb->data;
237	    sb->data = NULL;
238	    sb->len = 0;
239	    sb->cap = 0;
240	    return p;
241	}
