    /* Load a CJK-capable TrueType font here — inside the LVGL thread —
     * so glyph rasterization happens on the same thread that owns the
     * font handle.  The built-in bitmap fonts (montserrat = Latin only,
     * simsun_16_cjk = a ~1272-char subset that misses many simplified
     * chars like 这/个/态/经/办/张) cannot render arbitrary Chinese
     * reply text, so a full TTF is required for legible cards.
     *
     * Preference order:
     *   1. LV_USE_TINY_TTF + MiSans-Regular.ttf at /data/font/  (qemu:
     *      the data FAT image bundles the TTF; tiny_ttf needs no
     *      external FreeType library, just LVGL's stb_truetype port).
     *   2. LV_USE_FREETYPE + vg_font "MiSans-Medium"  (miwear only).
     *   3. built-in simsun_16_cjk / montserrat_14  (partial/latin). */
#if LV_USE_TINY_TTF
    if (!s_state.font) {
        /* Load MiSans-Regular.ttf fully into memory, then hand the buffer
         * to lv_tiny_ttf_create_data.  Using the in-memory variant (rather
         * than create_file) avoids keeping an lv_fs file stream open and
         * doing seek/read I/O on every glyph rasterization, which crashed
         * (data abort) on qemu when stb_truetype re-read the TTF during
         * render.  The TTF is a ~857 KB subset (3755 GB2312 level-1
         * common chars + ASCII + punctuation; subset from the 2.5 MB full
         * MiSans via fontTools — see docs).  The full 2.5 MB font caused
         * heap/TCB corruption (the large malloc fragmented the heap and
         * stb_truetype rasterization overran buffers, corrupting adjacent
         * chunk metadata → DEBUGASSERT in mm_foreach / nxsched_add_readytorun).
         * The 857 KB subset is small enough to avoid the fragmentation.
         *
         * Path note: the vela data FAT image is built by
         *   mcopy -i vela_data.bin -sv <board>/prebuilts/data/ ::
         * mcopy copies the source dir's CONTENTS into a subdir named after
         * the dir (data), so prebuilts/data/font/MiSans-Regular.ttf lands
         * at image root ::/data/font/... .  The image is mounted at /data
         * in NuttX, so the runtime path is /data/data/font/... . */
        const char* ttf_path = "/data/data/font/MiSans-Regular.ttf";
        int fd = open(ttf_path, O_RDONLY);
        if (fd >= 0) {
            struct stat st;
            if (fstat(fd, &st) == 0 && st.st_size > 0) {
                uint8_t* ttf_buf = malloc(st.st_size);
                if (ttf_buf) {
                    ssize_t n = read(fd, ttf_buf, st.st_size);
                    close(fd);
                    if (n == (ssize_t)st.st_size) {
                        s_state.font = lv_tiny_ttf_create_data(
                            ttf_buf, st.st_size, 18);
                        /* tiny_ttf references the buffer for the font's
                         * lifetime, so we must NOT free it here.  It is
                         * leaked intentionally (once per session). */
                    } else {
                        free(ttf_buf);
                        syslog(LOG_WARNING, "[%s] TTF read short: %zd/%lld\n",
                               TAG, n, (long long)st.st_size);
                    }
                } else {
                    close(fd);
                    syslog(LOG_WARNING, "[%s] TTF malloc(%lld) failed\n",
                           TAG, (long long)st.st_size);
                }
            } else {
                close(fd);
                syslog(LOG_WARNING, "[%s] TTF fstat failed: %s\n",
                       TAG, ttf_path);
            }
        } else {
            syslog(LOG_WARNING, "[%s] TTF open failed: %s (errno %d)\n",
                   TAG, ttf_path, errno);
        }
        if (s_state.font) {
            lv_obj_set_style_text_font(s_state.screen, s_state.font, 0);
            syslog(LOG_INFO, "[%s] MiSans TTF loaded via tiny_ttf (data)\n", TAG);
        }
    }
#endif
